def diff_even_odd(numbers):
    first_even = None
    first_odd = None

    for num in numbers:
        if first_even is None and num % 2 == 0:
            first_even = num
        if first_odd is None and num % 2 != 0:
            first_odd = num
        if first_even is not None and first_odd is not None:
            break

    if first_even is not None and first_odd is not None:
        return abs(first_even - first_odd)
    else:
        raise ValueError("The list must contain at least one even and one odd number.")

# Example usage
assert diff_even_odd([1, 3, 5, 7, 4, 1, 6, 8]) == 3
assert diff_even_odd([2, 4, 6, 1, 3, 5]) == 1
assert diff_even_odd([7, 9, 11, 2, 4, 6]) == 5
assert diff_even_odd([8, 10, 12, 1, 3, 5]) == 7
assert diff_even_odd([1, 2]) == 1
